import{_ as e,a as s}from"./chunks/tasks-eisenhower-view.Cm7aI_Bm.js";import{_ as a,H as n,f as o,i as r}from"./chunks/framework.CSxcEb-0.js";const i="/tempad/docs/screenshots/task-layouts.gif",l="/tempad/docs/screenshots/tasks-kanban-view.png",d="/tempad/docs/screenshots/eisenhower-drag.gif",y=JSON.parse('{"title":"Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),g={name:"guide/tasks.md"};function h(u,t,c,p,m,k){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h1><p>The <strong>Tasks</strong> view is where you create and triage work before it lands on the calendar.</p><p><img src="'+e+'" alt="Tasks list view"></p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><p>Switch layouts with the <strong>List</strong>, <strong>Board</strong>, and <strong>Matrix</strong> tabs in the Tasks toolbar. When <strong>Gantt view (beta)</strong> is enabled in Settings, a <strong>Gantt</strong> tab appears as well:</p><p><img src="'+i+'" alt="Switching task layouts"></p><h3 id="list-mode" tabindex="-1">List mode <a class="header-anchor" href="#list-mode" aria-label="Permalink to &quot;List mode&quot;">​</a></h3><p>Best for fast editing: search, complete tasks, and review metadata (due date, duration, list, priority, Eisenhower quadrant badge).</p><h3 id="kanban-mode" tabindex="-1">Kanban mode <a class="header-anchor" href="#kanban-mode" aria-label="Permalink to &quot;Kanban mode&quot;">​</a></h3><p>Columns follow your <strong>lists</strong>. Drag cards between columns to change list assignment or stage-style workflow.</p><p><img src="'+l+'" alt="Tasks Kanban view"></p><h3 id="eisenhower-matrix" tabindex="-1">Eisenhower matrix <a class="header-anchor" href="#eisenhower-matrix" aria-label="Permalink to &quot;Eisenhower matrix&quot;">​</a></h3><p>Sorts tasks into four quadrants by <strong>urgency</strong> and <strong>importance</strong> so you can decide what to do first, schedule, delegate, or defer.</p><p><img src="'+s+'" alt="Eisenhower matrix"></p><table tabindex="0"><thead><tr><th>Quadrant</th><th>Label</th><th>Typical use</th></tr></thead><tbody><tr><td>Q1</td><td><strong>Do first</strong></td><td>Urgent and important — deadlines, crises</td></tr><tr><td>Q2</td><td><strong>Schedule</strong></td><td>Important, not urgent — goals and planning</td></tr><tr><td>Q3</td><td><strong>Delegate</strong></td><td>Urgent, not important — interruptions, quick asks</td></tr><tr><td>Q4</td><td><strong>Later</strong></td><td>Neither urgent nor important — batch or drop</td></tr></tbody></table><p><strong>How placement works</strong></p><ul><li>Turn on <strong>Use task priorities</strong> in Settings to treat <strong>ASAP</strong> as always urgent/important (Q1).</li><li>Mark <strong>Important</strong> or <strong>Urgent</strong> on a task in the editor for explicit matrix placement.</li><li>Without flags, <strong>due date</strong> drives urgency (due today or within the next couple of days counts as urgent).</li><li>Drag cards between quadrants to update importance/urgency flags.</li></ul><p><img src="'+d+'" alt="Dragging a task between Eisenhower quadrants"></p><p><strong>Settings</strong></p><ul><li><strong>Show inbox tasks in Eisenhower matrix</strong> — include inbox/backlog items in the matrix (off by default).</li><li>List filters still apply: use sidebar chips to focus on Work, Personal, or Inbox.</li></ul><p>New users get sample tasks in each quadrant when the app seeds demo data on first load.</p><h3 id="gantt-mode-beta" tabindex="-1">Gantt mode (beta) <a class="header-anchor" href="#gantt-mode-beta" aria-label="Permalink to &quot;Gantt mode (beta)&quot;">​</a></h3><p>Off by default. Turn on <strong>Gantt view (beta)</strong> under <strong>Settings → Scheduler</strong>, then open <strong>Tasks</strong> and choose the <strong>Gantt</strong> layout tab.</p><p>Gantt is a <strong>timeline view</strong> of work that TemPad has already placed on your calendar — not a separate scheduling surface.</p><p><strong>What appears</strong></p><ul><li><strong>Auto-scheduled tasks</strong> that have at least one <strong>scheduled block</strong> (from <strong>Reschedule</strong> or prior scheduling).</li><li>One horizontal <strong>bar per task</strong> from the earliest block start to the latest block end (split tasks show as one combined bar).</li><li><strong>List color</strong> on the bar and a dot beside the task name in the sidebar (hidden in zen mode).</li><li><strong>Filled portion</strong> of the bar = progress (elapsed time in the scheduled window, or subtask completion when <strong>Subtasks (advanced)</strong> is on).</li><li><strong>Dependency arrows</strong> between tasks when <code>depends on</code> links exist among visible rows.</li><li><strong>Today</strong> column highlight and vertical line on the timeline.</li></ul><p><strong>What is excluded</strong></p><ul><li>Routines, inbox-only tasks, fixed-time tasks without scheduled blocks, and <strong>subtasks</strong> (parents only — same as other task layouts).</li><li>Tasks that are not <strong>auto-schedule</strong>.</li></ul><p><strong>Interaction</strong></p><ul><li>Click a <strong>task name</strong> (left) or its <strong>bar</strong> to open the task editor.</li><li>Use the Tasks <strong>search</strong> box and <strong>sidebar list filter</strong> — same as List/Kanban/Matrix.</li><li>Bars are <strong>read-only</strong> on the Gantt chart; change timing on the <strong>Calendar</strong> (drag blocks) or edit the task, then <strong>Reschedule</strong>.</li></ul><p><strong>Empty state</strong></p><p>If Gantt shows no rows, run <strong>Reschedule</strong> on the Calendar after ensuring tasks use <strong>Auto-schedule</strong> and have due dates and duration.</p><p><strong>Beta scope</strong></p><ul><li>No drag-to-reschedule on the Gantt chart itself (use Calendar).</li><li>No separate GCal export of Gantt segments.</li></ul><h2 id="scheduling-mode-task-editor" tabindex="-1">Scheduling mode (task editor) <a class="header-anchor" href="#scheduling-mode-task-editor" aria-label="Permalink to &quot;Scheduling mode (task editor)&quot;">​</a></h2><p>Use the <strong>Scheduling</strong> dropdown when editing a task:</p><ul><li><strong>Auto-schedule</strong> — TemPad finds time on your calendar within scheduling hours.</li><li><strong>Inbox</strong> — capture work for triage; it stays off the calendar until you promote it (switch mode, or set a due date / ASAP / Important+Urgent / <strong>Up first</strong> so it graduates on save).</li><li><strong>Fixed times</strong> — you set start and end; TemPad does not auto-place the task.</li></ul><p>Inbox and auto-schedule cannot apply at once. New tasks created while the Inbox filter is active start in <strong>Inbox</strong>.</p><h3 id="up-first-advanced" tabindex="-1">Up first (advanced) <a class="header-anchor" href="#up-first-advanced" aria-label="Permalink to &quot;Up first (advanced)&quot;">​</a></h3><p>When <strong>Up first flag (advanced)</strong> is on in Settings, auto-scheduled tasks can be marked <strong>Up first</strong> in the editor. On <strong>Reschedule</strong>, those tasks are placed before other tasks with the same priority and due date — <strong>routines still schedule first</strong>. The flag works alongside ASAP and Eisenhower; it only changes order among ordinary tasks.</p><p>Inbox tasks marked <strong>Up first</strong> are promoted to scheduling like ASAP tasks (they no longer need a due date to leave the inbox).</p><p>The task list shows a small <strong>up first</strong> badge when the flag is set and the setting is enabled.</p><h2 id="creating-tasks" tabindex="-1">Creating tasks <a class="header-anchor" href="#creating-tasks" aria-label="Permalink to &quot;Creating tasks&quot;">​</a></h2><p>When adding a task, set at minimum:</p><ul><li><strong>Title</strong></li><li><strong>List</strong> (or default list from Settings)</li><li><strong>Due date</strong> — required for scheduling placement</li><li><strong>Duration</strong> — minutes of work the scheduler should allocate</li></ul><p>Optional: priority (if enabled in Settings), <strong>Important</strong> / <strong>Urgent</strong> for Eisenhower, dependencies, splittable flag, notes, repeat rules.</p><h3 id="smart-editor-layout-primary-vs-more-options" tabindex="-1">Smart editor layout (primary vs More options) <a class="header-anchor" href="#smart-editor-layout-primary-vs-more-options" aria-label="Permalink to &quot;Smart editor layout (primary vs More options)&quot;">​</a></h3><p>When <strong>Smart task editor</strong> is on in <strong>Settings → Scheduler</strong> (default), the task editor shows a small <strong>primary</strong> set of fields and collapses the rest under <strong>More options</strong>.</p><ul><li><strong>Primary</strong> always includes essentials such as list, scheduling mode, duration, and due date.</li><li><strong>More options</strong> holds fields you use less often (repeat, dependencies, splittable, notes, and similar).</li><li>Which fields stay primary is <strong>inferred from your saved tasks</strong> (roughly: fields you use on at least 15% of tasks, once you have at least five tasks). The layout refreshes when you save a task and when you open the editor.</li><li>Editing a task that uses a field tucked under More options <strong>expands More options</strong> automatically so nothing is hidden.</li><li>New accounts with fewer than five tasks see <strong>all fields</strong> until there is enough history to collapse.</li><li>Turn off <strong>Smart task editor</strong> or turn on <strong>Show all task fields</strong> to always see the full form.</li></ul><h2 id="list-filters" tabindex="-1">List filters <a class="header-anchor" href="#list-filters" aria-label="Permalink to &quot;List filters&quot;">​</a></h2><p>Use <strong>sidebar list chips</strong> to focus on one list (including Inbox). Filtering hides other lists from task views and can affect what you see on the calendar sidebar context.</p><h2 id="subtasks-advanced" tabindex="-1">Subtasks (advanced) <a class="header-anchor" href="#subtasks-advanced" aria-label="Permalink to &quot;Subtasks (advanced)&quot;">​</a></h2><p>Off by default. Turn on <strong>Subtasks (advanced)</strong> under <strong>Settings → Scheduler</strong> to break a parent task into ordered steps.</p><ul><li>Add subtasks on a <strong>parent</strong> task in the editor (title and duration per step).</li><li>Only the <strong>parent</strong> is auto-scheduled; subtasks inherit list and scheduling hours and do not schedule on their own.</li><li>Parent <strong>duration</strong> is the rollup of incomplete subtask durations (read-only while subtasks exist).</li><li>On the <strong>calendar</strong>, subtasks appear as chips inside the parent’s scheduled time. When the parent is <strong>splittable</strong> and the scheduler places it in multiple blocks, subtasks are <strong>distributed across those blocks in order</strong>—each block shows only the steps assigned to that slot (a step may still appear if it is longer than the slot). When the parent fits in a single block, all steps appear together. Click a chip to open that subtask; click the parent chrome to edit the parent.</li><li>In <strong>list</strong> layout, expand a parent row to see nested subtasks; a <strong>2/5</strong> badge shows completion progress.</li><li>Completing all subtasks marks the parent complete; completing the parent completes all subtasks.</li><li>With the setting off, subtasks stay in your data but are hidden from task lists until you turn the feature back on.</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Link tasks so one must finish before another starts. The scheduler uses a topological sort; cycles are rejected.</p><p><strong>Drop task onto task</strong> (Settings → Theme): In List, Kanban, and Matrix, drag one incomplete task onto another. Default <strong>Create subtask</strong> nests the dragged task under the target (requires <strong>Subtasks (advanced)</strong>). <strong>Create dependency</strong> links them instead.</p><p><strong>Dependency drag direction</strong> (Settings): when drop mode is <strong>Create dependency</strong>, controls whether the target depends on the dragged task or the reverse — match your mental model and stick to one setting.</p><h2 id="repeating-tasks" tabindex="-1">Repeating tasks <a class="header-anchor" href="#repeating-tasks" aria-label="Permalink to &quot;Repeating tasks&quot;">​</a></h2><p>Tasks with a <strong>repeat</strong> rule get one scheduled occurrence per due date. To remove part of the series, open a block on the <strong>Calendar</strong> and use <strong>Delete</strong> → <strong>This occurrence</strong>, <strong>This and following</strong>, or <strong>All occurrences</strong> (see <a href="./calendar#deleting-recurring-items">Calendar — Deleting recurring items</a>).</p><h2 id="completion-and-auto-schedule" tabindex="-1">Completion and auto-schedule <a class="header-anchor" href="#completion-and-auto-schedule" aria-label="Permalink to &quot;Completion and auto-schedule&quot;">​</a></h2><p>Completing a task removes it from scheduling. Editing due date, duration, list hours profile, or dependencies triggers a reschedule pass (same as adding/deleting tasks).</p><p>See <a href="./calendar">Calendar</a> for placement and lock behavior after tasks are scheduled.</p>',63)])])}const w=a(g,[["render",h]]);export{y as __pageData,w as default};
